import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        StreamTokenizer st = new StreamTokenizer(new BufferedInputStream(System.in));
        st.resetSyntax();
        st.wordChars('!', '~');
        st.whitespaceChars(0, ' ');
        st.nextToken();
        int n = Integer.parseInt(st.sval);
        long[] a = new long[n];
        for (int i = 0; i < n; i++) { st.nextToken(); a[i] = Long.parseLong(st.sval); }
        StringBuilder out = new StringBuilder();
        long k = 0;
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                long p = Math.abs(a[i]), q = Math.abs(a[j]);
                // With a = min, b = max of |x|, |y|: condition 2 always holds, condition 1 is b <= 2a.
                if (Math.max(p, q) <= 2 * Math.min(p, q)) {
                    k++;
                    out.append(a[i]).append(' ').append(a[j]).append('\n');
                }
            }
        }
        PrintWriter pw = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));
        pw.println(k);
        pw.print(out);
        pw.flush();
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
)

func abs(x int64) int64 {
	if x < 0 {
		return -x
	}
	return x
}

func main() {
	reader := bufio.NewReader(os.Stdin)
	var n int
	fmt.Fscan(reader, &n)
	a := make([]int64, n)
	for i := range a {
		fmt.Fscan(reader, &a[i])
	}
	out := []byte{}
	k := 0
	for i := 0; i < n; i++ {
		for j := i + 1; j < n; j++ {
			p, q := abs(a[i]), abs(a[j])
			// With a = min, b = max of |x|, |y|: condition 2 always holds, condition 1 is b <= 2a.
			if max(p, q) <= 2*min(p, q) {
				k++
				out = strconv.AppendInt(out, a[i], 10)
				out = append(out, ' ')
				out = strconv.AppendInt(out, a[j], 10)
				out = append(out, '\n')
			}
		}
	}
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	fmt.Fprintln(w, k)
	w.Write(out)
}
